#!/usr/bin/env python3

"""
Script to reproduce the pdftk issue on systems without pdftk installed
"""

import sys
import os
sys.path.insert(0, '.')

def test_check_pdftool():
    """Test the check_pdftool function"""
    print("Testing check_pdftool function...")

    try:
        from paper2remarkable.utils import check_pdftool

        # Test with non-existing pdftk and existing qpdf
        try:
            result = check_pdftool("nonexistent_pdftk", "qpdf")
            print(f"check_pdftool with nonexistent pdftk and qpdf: {result}")
        except Exception as e:
            print(f"Error with nonexistent pdftk: {e}")

        # Test with both non-existing
        try:
            result = check_pdftool("nonexistent_pdftk", "nonexistent_qpdf")
            print(f"Both nonexistent: {result}")
        except Exception as e:
            print(f"Error with both nonexistent: {e}")

    except ImportError as e:
        print(f"Import error: {e}")

def test_provider_initialization():
    """Test provider initialization that might trigger the error"""
    print("\nTesting provider initialization...")

    try:
        from paper2remarkable.providers.arxiv import Arxiv

        # Try to initialize with nonexistent pdftk path
        try:
            provider = Arxiv(
                verbose=True,
                upload=False,
                pdftk_path="nonexistent_pdftk",
                qpdf_path="qpdf"  # assuming qpdf exists
            )
            print(f"Provider initialized with pdftool: {provider.pdftool}")
        except Exception as e:
            print(f"Error initializing provider: {e}")
            import traceback
            traceback.print_exc()

    except ImportError as e:
        print(f"Import error: {e}")

if __name__ == "__main__":
    test_check_pdftool()
    test_provider_initialization()

