"""

import sys
import os
sys.path.insert(0, '.')

def test_all_scenarios():
    """Test all scenarios for check_pdftool"""
    print("=== Comprehensive check_pdftool tests ===")

    from paper2remarkable.utils import check_pdftool, NoPDFToolError

    test_cases = [
        # (description, pdftk_path, qpdf_path, expected_result)
        ("Both tools available", "pdftk", "qpdf", "pdftk"),  # pdftk should be preferred
        ("Only qpdf available", "/usr/bin/nonexistent_pdftk", "qpdf", "qpdf"),
        ("Only pdftk available", "pdftk", "/usr/bin/nonexistent_qpdf", "pdftk"),
        ("Neither available", "/usr/bin/nonexistent_pdftk", "/usr/bin/nonexistent_qpdf", "error"),
    ]

    for description, pdftk_path, qpdf_path, expected in test_cases:
        print(f"\nTest: {description}")
        try:
            result = check_pdftool(pdftk_path, qpdf_path)
            if expected == "error":
                print(f"FAIL: Expected error but got '{result}'")
            elif result == expected:
                print(f"PASS: Got expected result '{result}'")
            else:
                print(f"UNEXPECTED: Expected '{expected}' but got '{result}'")
        except NoPDFToolError:
            if expected == "error":
                print(f"PASS: Correctly raised NoPDFToolError")
            else:
                print(f"FAIL: Unexpected NoPDFToolError, expected '{expected}'")
        except Exception as e:
            print(f"FAIL: Unexpected exception: {e}")

