    """Test edge cases"""
    print("\n=== Edge case tests ===")

    from paper2remarkable.utils import check_pdftool, NoPDFToolError

    # Test with None values
    print("\nTest: None values")
    try:
        result = check_pdftool(None, None)
        print(f"Unexpected success with None values: {result}")
    except NoPDFToolError:
        print("PASS: Correctly handled None values")
    except Exception as e:
        print(f"Handled None values with exception: {e}")

