    print("\nTest: Empty strings")
    try:
        result = check_pdftool("", "")
        print(f"Result with empty strings: {result}")
    except NoPDFToolError:
        print("PASS: Correctly handled empty strings")
    except Exception as e:
        print(f"Handled empty strings with exception: {e}")

if __name__ == "__main__":
    test_all_scenarios()
    test_edge_cases()

